select public.add_site_release('0.87.0','Игры: повторный визит, снимки и «неизвестный пациент» в «Приёме пациента»',
  jsonb_build_array(
    jsonb_build_object('kind','new','scope','game','min_rank',1,'text','В «Приёме пациента» появился повторный визит: после назначений пациент приходит на контроль с новыми анализами, и нужно скорректировать дозу или заметить осложнение (болезнь Грейвса, синдромы Кальмана и Клайнфельтера, язва двенадцатиперстной кишки).'),
    jsonb_build_object('kind','new','scope','game','min_rank',1,'text','ЭКГ, кариотип, сцинтиграфия, МРТ и рентген теперь показываются рисунком: в обычном режиме с заключением, в хардкоре без описания — снимок нужно оценить самому.'),
    jsonb_build_object('kind','improved','scope','game','min_rank',1,'text','На вкладках случаев больше нет имён пациентов, а порядок случаев в теме у каждого свой: по номеру случая диагноз не угадать.'),
    jsonb_build_object('kind','improved','scope','game','min_rank',1,'text','В итоге случая, составленного по опубликованному наблюдению, указан источник.')
  ),
  '2026-11-20 15:00:00+05');
